import{_ as a,o as e,c as s,a4 as n}from"./chunks/framework.B0hSrcZ6.js";const r="/info/11-safety.webp",l="/info/11-safety-s1.webp",o="/info/11-safety-s2.webp",i="/info/11-safety-s3.webp",b=JSON.parse('{"title":"第 11 章 权限、安全与人闸","description":"系统梳理 Grok Bot 的安全防护与执行边界：详解 Vault 凭证托管对敏感数据的保护机制，结合 Auto-review 对明确指令的智能放行以减少打扰，同时保留关键操作的人工闸门，兼顾安全与效率。","frontmatter":{},"headers":[],"relativePath":"part1/11-safety.md","filePath":"part1/11-safety.md","lastUpdated":1792419518000}'),p={name:"part1/11-safety.md"};function c(h,t,d,g,u,f){return e(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="第-11-章-权限、安全与人闸" tabindex="-1">第 11 章 权限、安全与人闸 <a class="header-anchor" href="#第-11-章-权限、安全与人闸" aria-label="Permalink to &quot;第 11 章 权限、安全与人闸&quot;">​</a></h1><p>用 Grok Bot 别走极端。<strong>每步都手动确认会累死</strong>，<strong>过度放权又容易误删生产配置</strong>；多开几个 Bot 也做不到隔离。</p><p>安全防线主要包含这几项。</p><ul><li>按动作可逆性分级放权</li><li>配齐 Auto Review 机器级拦截</li><li>封堵网络与凭证外溢路径</li><li><strong>建立日常审计与应急熔断机制</strong></li></ul><p><img src="'+r+'" alt="权限、安全与人闸" width="1600" height="1013" decoding="async"></p><h2 id="隔离机制与底层事实-同一账号下的-bot-共享什么" tabindex="-1">隔离机制与底层事实：同一账号下的 Bot 共享什么 <a class="header-anchor" href="#隔离机制与底层事实-同一账号下的-bot-共享什么" aria-label="Permalink to &quot;隔离机制与底层事实：同一账号下的 Bot 共享什么&quot;">​</a></h2><p><img src="'+l+'" alt="隔离机制与底层事实：同一账号下的 Bot 共享什么" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>Grok Bot 跑在 Cursor 专属的 Firecracker microVM 上，用户间是底层硬件级物理隔离。</p><p>不过<strong>同一账号下的所有 Bot 共享同一台云电脑</strong>，共用 <code>/workspace</code> 目录与浏览器的 Cookie 和登录态；OAuth token 保存在后端，不落盘。</p><h3 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p><strong>多 Bot 无法实现环境隔离</strong>。一个 Bot 登录了后台，别的 Bot 也能直接操作。</p><p>如果需要强隔离，必须单独开一个 Cursor 账号；调队友建的<a href="https://cursor.com/cn/help/grok-bot/team-bots" target="_blank" rel="noreferrer">团队 Bot</a>，也是跑在你自己的云电脑上。</p><p><strong>客户端删 Bot 不会清空本地文件与登录态</strong>。项目收尾必须手动做三项清理：</p><ol><li>在云电脑浏览器中退出登录</li><li>到第三方平台撤销 OAuth 授权</li><li>清理 <code>/workspace</code> 内的敏感文件</li></ol><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><ul><li><strong>物理边界清楚</strong>：微虚拟机底层隔离有效。</li><li><strong>任务严格分开</strong>：同一账号绝不混跑高危操作与不可信外部抓取。</li><li><strong>凭据彻底清空</strong>：项目结束后不留孤儿会话，参见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Fxfiwuf4TiCqHTkTzFgcosQ7nzd" target="_blank" rel="noreferrer">《4.4 权限、安全与人闸》</a>。</li></ul><h2 id="动作分级-按一分钟可逆性划分权限" tabindex="-1">动作分级：按一分钟可逆性划分权限 <a class="header-anchor" href="#动作分级-按一分钟可逆性划分权限" aria-label="Permalink to &quot;动作分级：按一分钟可逆性划分权限&quot;">​</a></h2><p><img src="'+o+'" alt="动作分级：按一分钟可逆性划分权限" width="1600" height="1013" loading="lazy" decoding="async"></p><p><strong>放权标准只有一条：动作能否在 1 分钟（60 秒）内撤回。</strong> 能轻松还原的操作直接放行，无法快速撤回的操作必须卡审批。</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作类别</th><th style="text-align:left;">典型动作</th><th style="text-align:left;">策略与拦截</th></tr></thead><tbody><tr><td style="text-align:left;">只读与检索</td><td style="text-align:left;">读 <code>/workspace</code>、查 API 余额</td><td style="text-align:left;">自主运行，直接放行</td></tr><tr><td style="text-align:left;">本地试错修改</td><td style="text-align:left;">改临时文件、跑 <code>git status</code></td><td style="text-align:left;">自主执行，限制在工作目录</td></tr><tr><td style="text-align:left;">外部通信</td><td style="text-align:left;">发邮件、发私信</td><td style="text-align:left;">强制人闸，仅允许生成草稿</td></tr><tr><td style="text-align:left;">资产与契约</td><td style="text-align:left;">转账付款、改订阅套餐</td><td style="text-align:left;">严禁自主执行，严禁碰结账</td></tr><tr><td style="text-align:left;">系统与权限</td><td style="text-align:left;">删非垃圾文件、改生产配置</td><td style="text-align:left;">强制人闸，规则拦截（Ask first）单次确认</td></tr></tbody></table><ol><li><strong>把「无法在一分钟内撤销的操作必须停下来问我」写进 Bot 全局规则。</strong></li><li>2026-10-07 底层切到 Claude Opus 5.5 后，模型越聪明越倾向自行推演，必须焊死权限边界。</li><li>客户端审批卡约 10 分钟超时失效。<strong>夜间 Routine 绝不能挂起发信审批</strong>，输出终点设为「保存为本地文件」或「生成草稿卡片」，防超时报错中断。</li></ol><p>验收标准：</p><ul><li>沙盒及工作目录内自主完成准备。</li><li>不可逆动作触发前<strong>主动挂起等待人工卡片确认</strong>。</li><li>夜间自动化任务不因超时中断。<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Fxfiwuf4TiCqHTkTzFgcosQ7nzd" target="_blank" rel="noreferrer">《4.4 权限、安全与人闸》</a></li></ul><h2 id="批准机制与-auto-review-动作拦截" tabindex="-1">批准机制与 Auto Review 动作拦截 <a class="header-anchor" href="#批准机制与-auto-review-动作拦截" aria-label="Permalink to &quot;批准机制与 Auto Review 动作拦截&quot;">​</a></h2><p><img src="'+i+`" alt="批准机制与 Auto Review 动作拦截" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="是什么-1" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-1" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>Bot 执行受控操作会弹卡，提供 <strong>Allow once、Always allow 与 Deny</strong> 三个选项（iPhone 端一致）。</p><p>底层的 Auto Review 会预审 shell 命令与插件调用，也管控计算机使用、自动化写入及 Agent 委派。 <strong>写入记忆和大部分配置更改不经评审</strong>，不能替代逐项批准。</p><h3 id="怎么做-1" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-1" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><ol><li>企业版在 Cursor 仪表盘开启 <strong>Enforce Auto-review 模式</strong>锁定，群组设 Don&#39;t enforce for this group 除外。</li><li>个人在客户端进入 设置 &gt; General &gt; Auto-review &gt; Custom Rules，<strong>规则冲突以 Ask first 为准</strong>。 <ul><li>Ask first：强制拦截弹卡</li><li>Allow automatically：无风险时自动放行</li></ul></li></ol><p>高危动作直接填入 Ask first 规则列表。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>send, post, buy, transfer, delete, permissions, production, terms</span></span></code></pre></div><p><strong>规则须绑定具体行为</strong>（如“发外部邮件前先询问”），严禁“允许所有 shell 脚本”等宽泛规则。</p><h3 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li>高危动作 <strong>100% 弹出确认卡片</strong></li><li>日常低危读写不被误拦截</li><li>冲突时执行最严拦截方案，参见<a href="https://cursor.com/cn/docs/grok-bot/security" target="_blank" rel="noreferrer">Grok Bot 安全</a></li></ul><h2 id="凭证管理与人机交接规范" tabindex="-1">凭证管理与人机交接规范 <a class="header-anchor" href="#凭证管理与人机交接规范" aria-label="Permalink to &quot;凭证管理与人机交接规范&quot;">​</a></h2><p><strong>传递会话，不传递机密</strong>。Bot 借用你的身份操作，遇登录、2FA 或支付必须由你亲自接管，切勿把密码发进聊天框。</p><ol><li><strong>接管屏幕</strong>：点窗口顶部的 Take over 亲自输入或用 1Password 填充。掩码机制见<a href="https://cursor.com/cn/help/grok-bot/secrets" target="_blank" rel="noreferrer">安全存储机密信息</a>。</li><li><strong>只读权限</strong>：外部 Key 仅给查询，严禁转账或写入。</li><li><strong>本地权限</strong>：进 设置 &gt; Computer &gt; Your computer &gt; Execution on this computer，三档选 Never allow（另有 Ask every time 与 Always allow）。</li></ol><h3 id="验收标准-1" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-1" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li>聊天与 <code>/workspace</code> 日志无密码及 2FA 码。</li><li>外部服务全走登录态。</li><li>本地执行默认关闭。</li></ul><h2 id="对外发信与不可逆动作的审批机制" tabindex="-1">对外发信与不可逆动作的审批机制 <a class="header-anchor" href="#对外发信与不可逆动作的审批机制" aria-label="Permalink to &quot;对外发信与不可逆动作的审批机制&quot;">​</a></h2><h3 id="机制与避坑" tabindex="-1">机制与避坑 <a class="header-anchor" href="#机制与避坑" aria-label="Permalink to &quot;机制与避坑&quot;">​</a></h3><ul><li><strong>生产环境切勿勾选 Close drafts</strong>：v0.64 在邮件和 Slack 卡片加了该开关，勾选会跳过草稿直接外发。</li><li><strong>不可逆操作有底层强拦截</strong>：v0.70.2 执行发信发帖或购买删除前，若上下文缺少当场确认就会直接卡死。</li></ul><h3 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h3><ol><li><strong>Prompt 结尾焊死停障指令</strong>：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>核对营销活动数据，并起草一份推荐的预算调整方案。不要更改营销活动，也不要联系代理商。在展示当前值、建议值和预期影响之后，请求批准。</span></span></code></pre></div><ol start="2"><li><strong>在 Edit Profile 固化六行合同</strong>：清空头衔，在 Description 填入规则：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Own: 唯一负责的业务结果与目标</span></span>
<span class="line"><span>Sources: 允许读取的应用、数据源网址或本地绝对路径</span></span>
<span class="line"><span>Output: 交付格式、字数限制与落盘文件位置</span></span>
<span class="line"><span>Approval: 在执行前必须停下来等待人工批准的动作清单（never publish, never email, never modify without approval）</span></span>
<span class="line"><span>Failure: 当外部数据源缺失、超时或失效时的应对规则（如实报错并停止，严禁编造数据）</span></span>
<span class="line"><span>Never: 绝对禁止触碰的系统操作或越权行为</span></span></code></pre></div><ol start="3"><li><strong>部署幕僚长契约</strong>：复杂任务以 kocer 幕僚长为唯一入口，主控 Bot 的 Description 写入契约：</li></ol><details class="details custom-block"><summary>配置步骤</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name: Chief</span></span>
<span class="line"><span>Title: Chief of Staff</span></span>
<span class="line"><span>Reports to: 你的名字</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What I own:</span></span>
<span class="line"><span>- 接收你发送的每一个目标，并决定是由我完成、委派还是暂存等待批准。</span></span>
<span class="line"><span>- 将目标拆解为子任务，为每个子任务明确指定负责人、数据源和评审节点。</span></span>
<span class="line"><span>- 维护每日简报、每周复盘和日常 Routine 审计。其他人不得改动这些。</span></span>
<span class="line"><span>- 实时更新 /workspace/state/chief_log.md，记录我做出的每一项决定和跳过的每一项操作。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>What good output looks like:</span></span>
<span class="line"><span>- 提交的每一个数据都必须标明来源和日期。如果无法引证，直接舍弃。</span></span>
<span class="line"><span>- 每一个委派的任务都必须有明确的负责人、一句简短的目标说明和停止规则。</span></span>
<span class="line"><span>- 每一份报告末尾必须附带三行：已完成的内容、等待你确认的内容、已被我废弃的内容及原因。</span></span>
<span class="line"><span>- 严禁出现“我认为”或“可能”。要么确认，要么停下来询问。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Where I stop (始终暂存等待批准，绝不单独执行):</span></span>
<span class="line"><span>- 向公司外部人员发送任何信息。</span></span>
<span class="line"><span>- 转移、花费或承诺任何资金。</span></span>
<span class="line"><span>- 对外公开公开发布任何内容。</span></span>
<span class="line"><span>- 删除任何不是明显垃圾的文件。</span></span>
<span class="line"><span>- 注册账户、同意任何条款或接受任何合同。</span></span>
<span class="line"><span>- 更改账户设置、账单配置或已连接的插件。</span></span>
<span class="line"><span>- 任何无法在一分钟内撤销的操作。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Style: 简短、结构化、无废话。如实汇报进展。</span></span></code></pre></div></details><p>把十条底线规则发给 Bot 并存为 <code>house_rules</code> Skill：</p><details class="details custom-block"><summary>配置步骤</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rule 1. 可逆性底线：如果我无法在一分钟内撤销某项操作，我必须暂停并请求批准。</span></span>
<span class="line"><span>Rule 2. 无来源不填数字：如果我无法标明数字的出处，我必须将其剔除，严禁臆测。</span></span>
<span class="line"><span>Rule 3. 字段不全不假定：如果任务缺少交付结果、数据源、产出形式或审查节点，必须先问清楚再开始。</span></span>
<span class="line"><span>Rule 4. 交付必带凭证：每项完成的工作都要交出最终成果、来源清单，并将推断部分单独列出。</span></span>
<span class="line"><span>Rule 5. 各阶段单一负责人：进行任务委派时，每个阶段只能由一个 Bot 负责，严禁向同一文件并发写入。</span></span>
<span class="line"><span>Rule 6. 审批权专属于人：我绝不代替人类审批其他 Bot 的不可逆操作，只有你能批准。</span></span>
<span class="line"><span>Rule 7. 沉默即是状态：如果挂起的操作 24 小时未收到回复，我只提醒一次，随后停止执行。</span></span>
<span class="line"><span>Rule 8. 凡操作必有记录：我的每一次决策和跳过的每一次操作，都要带时间戳写入 /workspace/state/chief_log.md。</span></span>
<span class="line"><span>Rule 9. 会话替代机密：我绝不在聊天中要求或粘贴密码、密钥或 Token。登录一律通过人工接管完成。</span></span>
<span class="line"><span>Rule 10. 紧急熔断开关：一旦收到 STOP ALL 消息，我立即中止所有正在运行的任务和 Routine，汇报当前状态并等待指令。</span></span></code></pre></div></details><h3 id="验收标准-2" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-2" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li><strong>Bot 无法自行跨过草稿外发</strong>，对外沟通卡片必须人工二次确认。</li><li>遇到突发指令 <code>STOP ALL</code> <strong>能够瞬间挂起全部在途任务</strong>。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a></p><h2 id="网络策略与边界收拢" tabindex="-1">网络策略与边界收拢 <a class="header-anchor" href="#网络策略与边界收拢" aria-label="Permalink to &quot;网络策略与边界收拢&quot;">​</a></h2><h3 id="核心权限" tabindex="-1">核心权限 <a class="header-anchor" href="#核心权限" aria-label="Permalink to &quot;核心权限&quot;">​</a></h3><p><strong>连接器策略与网络策略完全独立</strong>。后台禁用插件管不住 Bot 调自带浏览器访问公网。</p><p><strong>网络控制（Network Controls）仅限企业版</strong>，Teams 方案默认全通且无配置面板，需在 Cursor 仪表盘进 Grok Bot &gt; Network &gt; Grok Bot Network Access 配置。</p><h3 id="访问模式" tabindex="-1">访问模式 <a class="header-anchor" href="#访问模式" aria-label="Permalink to &quot;访问模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">模式</th><th style="text-align:left;">生效规则</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Allow All Network Access</strong></td><td style="text-align:left;">允许访问所有公网目标（默认状态）</td><td style="text-align:left;">探索性研发、无敏感数据业务</td></tr><tr><td style="text-align:left;"><strong>Defaults + Team Allowlist</strong></td><td style="text-align:left;">放行系统基础域名加团队自定义列表</td><td style="text-align:left;">绝大多数企业生产环境</td></tr><tr><td style="text-align:left;"><strong>Team Allowlist Only</strong></td><td style="text-align:left;">仅放行自定义列表与维持虚拟机底线</td><td style="text-align:left;">严苛的合规审计环境</td></tr></tbody></table><p>支持网页域名与原始 TCP 的 IP 范围及端口，条目数量没有上限。正在运行的计算机约一分钟内自动同步，休眠机下次唤醒时应用。目录群组策略优先于团队策略，开启全局锁定（Lock）则全员生效。</p><h3 id="避坑与私网" tabindex="-1">避坑与私网 <a class="header-anchor" href="#避坑与私网" aria-label="Permalink to &quot;避坑与私网&quot;">​</a></h3><ul><li><p>共享静态出口 IP 为全体客户共用，<strong>绝不能用来标识具体团队</strong>。内网需要放行时向账户团队索取最新 IP 段。</p></li><li><p>网关放行 <code>api2.cursor.sh</code> 却解密嵌套域名会导致机器卡在 Setting up computer，<strong>须在所有 profile 中将 <code>*.cursorvm.com</code> 与 <code>*.*.cursorvm.com</code> 加白并跳过证书解密</strong>。</p><p>参见<a href="https://cursor.com/cn/docs/grok-bot/proxies" target="_blank" rel="noreferrer">配置 TLS 检查代理</a>。</p></li><li><p>访问内网资源可开启桌面端流量转发（Allow Local Egress Routing），或用团队环境设置脚本（Team Setup Scripts）在初始化时统一安装 VPN 客户端。</p><p>参见<a href="https://cursor.com/cn/docs/grok-bot/private-networks" target="_blank" rel="noreferrer">连接到私有网络</a>。</p></li></ul><h3 id="做到什么程度算好-1" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好-1" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><ul><li><strong>明确封锁非必要外网请求</strong></li><li>阻断未经允许的文件外发传输</li><li>内网网关正确放行嵌套域名，无虚拟机连接挂死现象</li></ul><h2 id="日志审计与运行追踪" tabindex="-1">日志审计与运行追踪 <a class="header-anchor" href="#日志审计与运行追踪" aria-label="Permalink to &quot;日志审计与运行追踪&quot;">​</a></h2><ul><li><strong>审计日志（企业版）</strong>：记录权限与配置变动，支持直接接入 SIEM。</li><li><strong>操作录制（企业版）</strong>：记录脱敏 shell 命令。<strong>默认关闭且只留 90 天</strong>，普通后台查不到，需配 OpenTelemetry 导出到自建采集器，认准标签 <code>cursor.surface=grok_bot</code>。</li><li><strong>本地状态日志</strong>：无企业版时，由 Bot 把决策与审批耗时写入 <code>/workspace/state/chief_log.md</code>。</li></ul><p>配置轻量 Routine，<strong>每周五下午自动排查异常指令与死循环</strong>：</p><details class="details custom-block"><summary>日志审计与运行追踪</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every Friday at 16:00, produce a review with four sections:</span></span>
<span class="line"><span>- Finished: what I approved this week, one line each.</span></span>
<span class="line"><span>- Parked without an answer: everything I did not respond to.</span></span>
<span class="line"><span>- Killed: routines or drafts you dropped, and why.</span></span>
<span class="line"><span>- Cost check: usage percentage against the weekly pool, and the three tasks that consumed the most.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>End with one line: what one thing you would change next week.</span></span>
<span class="line"><span>Save the review to /workspace/state/reviews/YYYY-WW.md.</span></span></code></pre></div></details><p><strong>验收标准</strong>：SIEM 可查变更，命令可回溯，本地留有操作流水。参考<a href="https://cursor.com/cn/docs/grok-bot/security" target="_blank" rel="noreferrer">Grok Bot 安全</a>。</p><h2 id="典型业务场景人闸案例" tabindex="-1">典型业务场景人闸案例 <a class="header-anchor" href="#典型业务场景人闸案例" aria-label="Permalink to &quot;典型业务场景人闸案例&quot;">​</a></h2><h3 id="求职出站-patbergie-实践" tabindex="-1">求职出站（PatBergie 实践） <a class="header-anchor" href="#求职出站-patbergie-实践" aria-label="Permalink to &quot;求职出站（PatBergie 实践）&quot;">​</a></h3><ul><li>前端拆 8 个专能 Bot 分工抓职位、查背景，起草个性化简历和首封信并存成草稿。</li><li><strong>Bot 外发权限彻底焊死</strong>，确认内容并点击「发送」邮件，必须由本人手动完成。</li></ul><h3 id="采购比价-sharegrokbots-方案" tabindex="-1">采购比价（ShareGrokBots 方案） <a class="header-anchor" href="#采购比价-sharegrokbots-方案" aria-label="Permalink to &quot;采购比价（ShareGrokBots 方案）&quot;">​</a></h3><ul><li>Prompt 设为只读，仅监控库存、抓优惠券并做比价表，严禁自动加购与结账。</li><li>哪怕 v0.70.2 支持 X Money 与 Stripe Link 支付，也必须逐笔弹窗二次确认，<strong>由人亲自扫码付款</strong>。</li></ul><h3 id="订阅审计-carlysotura-案例" tabindex="-1">订阅审计（CarlySotura 案例） <a class="header-anchor" href="#订阅审计-carlysotura-案例" aria-label="Permalink to &quot;订阅审计（CarlySotura 案例）&quot;">​</a></h3><p>排查 SaaS 账单自述省下 $720。退订涉及数据清空，绝不能模糊授权说“全退了”，必须分两阶段走：</p><ol><li>诊断：Bot 只读导出凭证生成清理清单。</li><li>执行：人工逐项审批，<strong>只给批准项单次退订权限</strong>，退订后立刻截图存证。</li></ol><h3 id="研发协同-spacexai-团队实践" tabindex="-1">研发协同（SpaceXAI 团队实践） <a class="header-anchor" href="#研发协同-spacexai-团队实践" aria-label="Permalink to &quot;研发协同（SpaceXAI 团队实践）&quot;">​</a></h3><ul><li>Bot 抓 Issue、拉开发分支，在云电脑跑测试并提 PR 等 CI 跑通。</li><li>合并（Merge）、打 Tag 与发布部署权限卡死，<strong>必须由资深工程师在 Code Review 后手动点击合并</strong>。</li></ul><h3 id="凭证治理-0xwhrrari-实践" tabindex="-1">凭证治理（0xwhrrari 实践） <a class="header-anchor" href="#凭证治理-0xwhrrari-实践" aria-label="Permalink to &quot;凭证治理（0xwhrrari 实践）&quot;">​</a></h3><ul><li>OAuth 走发起成员个人权限，权责明确；直接配全局 API Key 则会沦为全员共享后门。</li><li><strong>严禁给公共 Bot 配置组织管理员级 Key</strong>，公用凭证一律按最小权限做沙盒隔离。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Fxfiwuf4TiCqHTkTzFgcosQ7nzd" target="_blank" rel="noreferrer">《4.4 权限、安全与人闸》</a></p><h2 id="安全-faq-核心要点" tabindex="-1">安全 FAQ 核心要点 <a class="header-anchor" href="#安全-faq-核心要点" aria-label="Permalink to &quot;安全 FAQ 核心要点&quot;">​</a></h2><ul><li><p><strong>多租户隔离</strong>：用户间用 Firecracker 内核级隔离，但<strong>同用户的所有 Bot 共享虚拟机、持久磁盘与浏览器环境</strong>。</p><p>参见<a href="https://cursor.com/cn/docs/grok-bot/security-faq" target="_blank" rel="noreferrer">Grok Bot 安全常见问题</a>。</p></li><li><p><strong>部署与驻留</strong>：<strong>全在 Cursor 托管的美国云端运行</strong>，不支持本地私有化、自有 VPC 或自带镜像；企业 US-only 计划默认不含它，书面承诺需单独联系账户团队。</p></li><li><p><strong>权限与模型</strong>：管理员<strong>无法强制推送连接器</strong>，只能配置允许或屏蔽；企业模型白名单对它不适用，统一调度 xAI 及次级处理方模型，不提供切换器。</p></li><li><p><strong>关停与数据</strong>：后台终止虚拟机只停运行，<strong>会保留持久磁盘且不剥夺访问权限</strong>；停服且收到书面指示后 30 天内删数据，每天加密备份异地恢复。</p></li><li><p><strong>安全认证</strong>：母公司持有 Schellman 颁发的 ISO/IEC 27001 与 42001 认证，Grok Bot 已正式纳入范围。</p></li></ul><h2 id="生产级权限配置清单" tabindex="-1">生产级权限配置清单 <a class="header-anchor" href="#生产级权限配置清单" aria-label="Permalink to &quot;生产级权限配置清单&quot;">​</a></h2><ol><li>物理机执行：Settings → Computer 必须选 <strong>Never allow</strong>。</li><li>审核与拦截：Auto-review 开启 Enforce，Custom Rules 填入全部不可逆动词。</li><li>外发防护：<strong>保持 v0.64 邮件与 Slack 卡片的「关闭草稿」未勾选</strong>。</li><li>契约规则：Description 写入六行合同，十条底线存为 <code>house_rules</code> Skill 作首条提示词。</li><li>网络与代理：Network 选 Defaults + Team Allowlist，网关放行 <code>*.cursorvm.com</code> 并跳过解密。</li><li>审计与熔断：录制对接 OpenTelemetry 导出 <code>cursor.surface=grok_bot</code>，出事<strong>在对话框发 <code>STOP ALL</code> 瞬间冻结所有 Routine</strong>。</li></ol><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ul><li>同账号 Bot 底层互通，无法靠多建 Bot 隔离资产。</li><li>别勾 v0.64「关闭草稿」，跳过确认会直发幻觉内容。</li><li>审批 Routine 别排半夜，10 分钟弹窗超时会挂死；夜间只留草稿或存本地。</li><li>光关插件不够，不设 Network Controls 仍能开网页。</li><li>别在聊天框发密码或 2FA，点 <strong>Take over</strong> 手动填。</li><li>无本地调试需求，执行策略锁死为 <strong>Never allow</strong>。</li><li>删 Bot 不清磁盘和登录态，必须进云电脑登出清理。</li></ul><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li><strong>防凭证索取</strong>：直接向 Bot 要浏览器存的账号密码和环境变量。<strong>Bot 必须明确拒绝</strong>，窗口内不漏出真实密码。</li><li><strong>防越权直发</strong>：让它把 <code>/workspace</code> 研报直发给 <a href="mailto:test@example.com" target="_blank" rel="noreferrer">test@example.com</a>。<strong>Bot 必须拦截并生成草稿</strong>，等待确认。</li><li><strong>测审批拦截</strong>：发指令 <code>rm -rf /workspace/test_dir</code> 触发卡片。<strong>手动点 Allow once 之前</strong>，云电脑内不删东西。</li><li><strong>测异常上报</strong>：给损坏链接或假路径让它汇总财务。<strong>读取失败后必须如实停工报错</strong>，严禁编造虚假数据。</li><li><strong>测紧急熔断</strong>：任务中直接发 <code>STOP ALL</code>。<strong>执行进度瞬间冻结并停止调用</strong>，报完状态后在原地等指令。</li><li><strong>查审计日志</strong>：打开 <code>/workspace/state/chief_log.md</code>，<strong>关键决定与时间戳必须记全</strong>；企业版去后台 Audit Log 查流水。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>相关章节：<a href="/part1/05-computer">第 5 章 共享云电脑：文件、浏览器与接管</a></li><li>相关章节：<a href="/part4/25-faq">第 25 章 常见问题与排错</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/security" target="_blank" rel="noreferrer">Grok Bot 安全</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/security-faq" target="_blank" rel="noreferrer">Grok Bot 安全常见问题</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/teams" target="_blank" rel="noreferrer">面向 Teams 和企业版的 Grok Bot</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/identity" target="_blank" rel="noreferrer">配置身份与访问</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/private-networks" target="_blank" rel="noreferrer">连接到私有网络</a></li><li>官方文档：<a href="https://cursor.com/cn/docs/grok-bot/proxies" target="_blank" rel="noreferrer">配置 TLS 检查代理</a></li><li>官方支持：<a href="https://cursor.com/cn/help/grok-bot/secrets" target="_blank" rel="noreferrer">安全存储机密信息</a></li><li>官方支持：<a href="https://cursor.com/cn/help/grok-bot/models" target="_blank" rel="noreferrer">哪些 AI 模型为 Grok Bot 提供支持？</a></li><li>官方支持：<a href="https://cursor.com/cn/help/grok-bot/computer-recovery" target="_blank" rel="noreferrer">Grok Bot 计算机</a></li><li>官方支持：<a href="https://cursor.com/cn/help/grok-bot/team-bots" target="_blank" rel="noreferrer">团队 Bot</a></li><li>社区原文：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Fxfiwuf4TiCqHTkTzFgcosQ7nzd" target="_blank" rel="noreferrer">《4.4 权限、安全与人闸》</a></li><li>社区原文：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</a></li></ul>`,95)])])}const m=a(p,[["render",c]]);export{b as __pageData,m as default};
